    /// <summary>
    /// Creates a <c>METSalesOrderConfirmedBusinessEventContract</c> from a <c>CustConfirmJour</c> record.
    /// </summary>
    /// <param name = "_custConfirmJour">A <c>CustConfirmJour</c> record.</param>
    /// <returns>A <c>SalesInvoicePostedBusinessEventContract</c>.</returns>
    public static METSalesOrderConfirmedBusinessEventContract newFromCustConfirmJour(CustConfirmJour _custConfirmJour)
    {
        var contract = new METSalesOrderConfirmedBusinessEventContract();
        contract.initialize(_custConfirmJour);

        return contract;
    }

    private void initialize(CustConfirmJour _custConfirmJour)
    {
        METSalesTable   metSalesTable;
        SalesTable      salesTable;

        salesTable= SalesTable::find(_custConfirmJour.SalesId);
        metSalesTable = metSalesTable::findByRefRecId(salesTable.RecId);

        orderAccount = _custConfirmJour.InvoiceAccount;
        confirmId = _custConfirmJour.ConfirmId;
        currencyCode = _custConfirmJour.CurrencyCode;
        confirmAmount = _custConfirmJour.ConfirmAmount;
        confirmDate = _custConfirmJour.ConfirmDate;
        salesId = _custConfirmJour.SalesId;
        legalEntity = _custConfirmJour.DataAreaId;
        industryKey = METCustTable::find(_custConfirmJour.OrderAccount).IndustryKey;
        salesOrderDate = salesTable.createDate();
        portalId = metSalesTable.PortalWebId;
        customerReference = salesTable.CustomerRef;
        webOrderDate = DateTimeUtil::date(metSalesTable.OrderDateTime);
        promotionId = metSalesTable.PromotionId;
        deliveryInstructions = metSalesTable.DeliveryInstructions;
        requestedShippingDate = salesTable.ShippingDateRequested;
    }

private void new()
{
}

